#!/usr/bin/env node
import {createReadStream,existsSync,readFileSync,statSync,writeFileSync} from 'node:fs';
import {join,resolve} from 'node:path';

const args=new Map();for(let index=2;index<process.argv.length;index++){const item=process.argv[index];if(item.startsWith('--')){const next=process.argv[index+1];args.set(item.slice(2),!next||next.startsWith('--')?true:process.argv[++index]);}}
const bundle=resolve(String(args.get('bundle')??'')),endpoint=String(args.get('endpoint')??'').replace(/\/$/,''),workspaceId=String(args.get('workspace-id')??''),token=String(args.get('access-token')??process.env.CLOUDFLARE_ACCESS_TOKEN??''),dryRun=args.has('dry-run'),statePath=join(bundle,'import-state.json');if(!bundle||!existsSync(join(bundle,'reconciliation.json')))throw new Error('--bundle must contain reconciliation.json');if(!dryRun&&(!endpoint||!workspaceId||!token))throw new Error('--endpoint, --workspace-id, and --access-token are required');const manifest=JSON.parse(readFileSync(join(bundle,'reconciliation.json'),'utf8'));if(manifest.workspaceId!==workspaceId&&!dryRun)throw new Error('bundle workspaceId does not match');if(manifest.r2Required?.length&&!dryRun){const r2StatePath=join(bundle,'r2-upload-state.json'),r2State=existsSync(r2StatePath)?JSON.parse(readFileSync(r2StatePath,'utf8')):null;if(!r2State?.completed||manifest.r2Required.some(item=>r2State.files?.[item.fileId]?.status!=='uploaded'))throw new Error(`copy and verify ${manifest.r2Required.length} required attachment objects in R2 before importing`);}const state=existsSync(statePath)?JSON.parse(readFileSync(statePath,'utf8')):{version:1,imports:{}};
const headers=extra=>({authorization:`Bearer ${token}`,'x-workspace-id':workspaceId,...extra});
for(const entry of manifest.files){if(state.imports[entry.objectType]?.status==='completed')continue;const path=join(bundle,entry.file),bytes=statSync(path).size;if(dryRun){state.imports[entry.objectType]={status:'validated',bytes,records:entry.records};continue;}const response=await fetch(`${endpoint}/api/crm/imports/upload`,{method:'POST',headers:headers({'content-type':'application/x-ndjson','content-length':String(bytes),'x-object-type':entry.objectType}),body:createReadStream(path),duplex:'half'});if(!response.ok)throw new Error(`${entry.objectType} upload failed (${response.status}): ${await response.text()}`);const result=await response.json(),id=result.data.id;state.imports[entry.objectType]={id,status:'pending',bytes,records:entry.records};writeFileSync(statePath,`${JSON.stringify(state,null,2)}\n`,{mode:0o600});for(let attempt=0;attempt<1800;attempt++){const statusResponse=await fetch(`${endpoint}/api/crm/import/${id}`,{headers:headers({})});if(!statusResponse.ok)throw new Error(`${entry.objectType} status failed (${statusResponse.status})`);const status=(await statusResponse.json()).data;state.imports[entry.objectType]={...state.imports[entry.objectType],...status};writeFileSync(statePath,`${JSON.stringify(state,null,2)}\n`,{mode:0o600});if(status.status==='completed')break;if(status.status==='failed'||status.status==='cancelled')throw new Error(`${entry.objectType} import ${status.status}: ${status.error??'unknown error'}`);await new Promise(resolve=>setTimeout(resolve,2000));if(attempt===1799)throw new Error(`${entry.objectType} import timed out`);}}
if(!dryRun){const response=await fetch(`${endpoint}/api/crm/reconciliation`,{method:'POST',headers:headers({'content-type':'application/json'}),body:JSON.stringify({sourceManifestSha256:manifest.sourceManifestSha256,expectedCounts:manifest.counts})});if(!response.ok)throw new Error(`target reconciliation failed (${response.status}): ${await response.text()}`);state.reconciliation=(await response.json()).data;if(state.reconciliation.status!=='passed')throw new Error(`target reconciliation failed: ${JSON.stringify(state.reconciliation)}`);}state.completed=true;writeFileSync(statePath,`${JSON.stringify(state,null,2)}\n`,{mode:0o600});console.log(JSON.stringify({bundle,dryRun,imports:state.imports,reconciliation:state.reconciliation??null},null,2));
